$ErrorActionPreference='Stop'; Write-Output ('FREDWIN_HOST=' + $env:COMPUTERNAME); $cmd='set +e; cd /home/ubuntu/mei-mg-email || exit 2; echo CHECK_BRT=$(TZ=America/Sao_Paulo date +%Y-%m-%dT%H:%M:%S%z); printf WORKER_BEFORE=; sudo systemctl is-active mei-mg-email-worker.service 2>/dev/null || true; printf ENABLED=; sudo systemctl is-enabled mei-mg-email-worker.service 2>/dev/null || true; printf NDR_GUARD=; sudo systemctl is-active mei-mg-email-ndr-guard.service 2>/dev/null || true; printf NDR_ENABLED=; sudo systemctl is-enabled mei-mg-email-ndr-guard.service 2>/dev/null || true; printf AUTOREPAIR=; sudo systemctl is-active mei-mg-email-autorepair.timer 2>/dev/null || true; if sudo test -f /var/lib/mei-mg-email/sender_blocked.pause; then echo SENTINEL=present; else echo SENTINEL=absent; fi; sudo systemctl show mei-mg-email-worker.service -p Restart -p RestartUSec -p StartLimitIntervalUSec -p ExecStart --no-pager 2>/dev/null || true; echo DB_BEFORE; sudo docker exec mei-mg-email-db pg_isready -U postgres -d mei_mg_email 2>/dev/null || true; echo PREFLIGHT_BEGIN; .venv/bin/python scripts/runtime_sender_preflight.py; echo PREFLIGHT_RC=$?; echo SUPERVISOR_BEGIN; .venv/bin/python scripts/nonstop_supervisor_15m.py; echo SUPERVISOR_RC=$?; echo DB_METRICS_BEGIN; sudo docker exec -i mei-mg-email-db psql -X -U postgres -d mei_mg_email -At -v ON_ERROR_STOP=0 <<"SQL"
set statement_timeout="15s";
select "SENT24="||count(*) from mei_email.envios where status::text in ("submitted","enviado","delivered") and enviado_em>=now()-interval "24 hours";
select "SENT10="||count(*) from mei_email.envios where status::text in ("submitted","enviado","delivered") and enviado_em>=now()-interval "10 minutes";
select "OPEN_TOTAL="||count(*) from mei_email.envios where status::text in ("pendente","enviando","pending","processing");
select "LAST_SENT="||coalesce(max(enviado_em)::text,"<null>") from mei_email.envios where status::text in ("submitted","enviado","delivered");
select "ACTIVE_CAMPAIGN="||exists(select 1 from mei_email.campanhas where status::text in ("enfileirada","em_andamento"));
select "STRICT_ELIGIBLE_EXISTS="||exists(select 1 from mei_email.vw_empresas_elegiveis limit 1);
select "STRICT_ELIGIBLE_CAPPED="||count(*) from (select cnpj from mei_email.vw_empresas_elegiveis limit 10000) s;
select "OPEN_REPLAY="||count(*) from mei_email.envios e where e.status::text in ("pendente","enviando","pending","processing") and exists(select 1 from mei_email.envios h where h.id<>e.id and h.status::text in ("submitted","enviado","delivered") and ((h.email is not null and e.email is not null and lower(h.email)=lower(e.email)) or (h.cnpj is not null and e.cnpj is not null and h.cnpj=e.cnpj)));
select "DUP_TERMINAL_EMAILS="||count(*) from (select lower(email) em from mei_email.envios where status::text in ("submitted","enviado","delivered") and email is not null group by lower(email) having count(*)>1) d;
select "LOCK_WAITERS="||count(*) from pg_stat_activity where wait_event_type="Lock";
select "BLOCKED_LOCKS="||count(*) from pg_locks where not granted;
select "LONG_ACTIVE="||count(*) from pg_stat_activity where state="active" and pid<>pg_backend_pid() and query_start<now()-interval "30 seconds";
select "FLYWAY_MAX="||coalesce(max(version::int),0) from public.flyway_schema_history where success=true and version~"^[0-9]+$";
select "FLYWAY_37_38="||count(*) from public.flyway_schema_history where success=true and version in ("37","38");
select "GUARD_TRIGGER_COUNT="||count(*) from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname="mei_email" and not t.tgisinternal and (pg_get_triggerdef(t.oid) ilike "%eligib%" or pg_get_triggerdef(t.oid) ilike "%copy%" or pg_get_triggerdef(t.oid) ilike "%replay%");
SQL
 echo DNS_GRAPH=$(getent hosts graph.microsoft.com >/dev/null 2>&1 && echo ok || echo fail); echo HTTPS_GRAPH=$(curl -sS -o /dev/null -w "%{http_code}" --connect-timeout 8 https://graph.microsoft.com/v1.0/ 2>/dev/null || echo fail); echo WORKER_AFTER=$(sudo systemctl is-active mei-mg-email-worker.service 2>/dev/null || true); echo STATE_BEGIN; sudo cat /var/lib/mei-mg-email/throughput-supervisor-state.json 2>/dev/null || true; echo STATE_END'; & ssh -o BatchMode=yes -o ConnectTimeout=15 shopvivaliz-vm $cmd; $rc=$LASTEXITCODE; Write-Output ('SSH_RC=' + $rc); exit 0
